const customizeBtn=document.getElementById('seopress-user-consent-customize');const saveBtn=document.getElementById('seopress-user-consent-save');const banner=panel.closest('.seopress-user-consent');panel.classList.toggle(HIDE_CLASS,!open);if(banner){banner.classList.toggle('seopress-user-consent-expanded',open)}
if(saveBtn){saveBtn.classList.toggle(HIDE_CLASS,!open)}
